#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
umask 077
SETUP_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
cd -- "$SETUP_ROOT"

if ! command -v python3 >/dev/null 2>&1 || ! python3 -c 'import sys; sys.exit(sys.version_info < (3, 11))'; then
  printf 'Setup needs Python 3.11 or newer. Install it, then rerun ./setup.sh.\n' >&2
  exit 1
fi
if [[ "$(uname -s)" != Linux ]]; then
  printf 'The background service needs Linux with a systemd user session.\n' >&2
  exit 1
fi

banner "PR review watcher setup"

stage "Tools and GitHub access"
for tool in node gh systemctl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "Missing command: $tool. Install it and rerun this wizard."
    exit 1
  fi
done
say "The watcher uses your GitHub identity to read PRs and request reviews."
if gh auth status --hostname github.com >/dev/null 2>&1; then
  say "GitHub login is already available."
else
  say "Complete the GitHub browser/device login when prompted."
  gh auth login --hostname github.com --web
fi
gh api user --jq '"Authenticated GitHub user: " + .login'

stage "Pi sign-in"
mapfile -t PI_COMMAND < <(python3 - <<'PYCODE'
from pathlib import Path
import tomllib
p=Path.home()/'.config/pr-review-watcher/config.toml'
c=tomllib.loads(p.read_text()) if p.exists() else {}
command=c.get('agent',{}).get('command')
if not command:
    managed=Path.home()/'.pi/agent/bin/pi'
    command=[str(managed)] if managed.is_file() else ['pi']
for part in command: print(part)
PYCODE
)
if ! command -v "${PI_COMMAND[0]}" >/dev/null 2>&1; then
  warn "Pi was not found. Install your normal Pi CLI and sign in, then rerun this wizard."
  exit 1
fi
say "Use your existing Pi provider login and model settings."
step "If you need to sign in: open Pi, enter /login, and follow the provider login."
step "Exit Pi when finished to return to setup. Existing sign-in can be kept."
if confirm "Open Pi now?"; then
  "${PI_COMMAND[@]}"
fi

stage "Slack notification workflow"
open_url "https://app.slack.com/client/"
step "Switch to the workspace that contains you and your intended recipients."
step "Open Workflows (under More or Agents & tools), then New workflow."
step "Choose the start event From a webhook."
step "Set up three Text variables named exactly: recipient, report, pr_url."
step "Add Send a message to a person; choose the recipient variable as the member."
step "In the message body, insert report, then a new line and pr_url."
note "Use Insert a variable so these are variable tokens, not typed names."
note "The report is plain text with emojis; backticks and bold markers render literally."
step "Name it PR review, save the step, and publish the workflow."
step "Reopen Starts with a webhook and copy its web request URL."
note "Keep the URL private. The next configuration step asks for it with hidden input."
note "If this workflow already exists, keep it and reuse its URL."
pause "Press Enter when the workflow is published and its URL is ready."

stage "Jira access (optional)"
say "Ticket-backed reviews need a local cookie export from your authenticated Jira session."
if confirm "Set up or refresh EA Flood Jira cookies now?"; then
  open_url "https://eaflood.atlassian.net/"
  step "Sign in with your normal account."
  step "Use your approved browser cookie exporter to save Netscape-format cookies."
  step "Save outside this checkout: ~/.agents/secrets/eaflood.atlassian.net_cookies.txt"
  step 'In another terminal: chmod 600 ~/.agents/secrets/eaflood.atlassian.net_cookies.txt'
  note "Setup also accepts another cookie path. Never paste cookie contents into chat."
  pause "Press Enter when the export is saved."
else
  note "Existing cookies can be kept. Missing cookies will block Jira-backed reviews."
fi

stage "Configure and install"
say "Enter keeps defaults. New installations start by watching only your own PRs."
say "Existing settings and recipient mappings are preserved; review the enabled-author summary."
say "The installer saves local config, the private webhook, a launcher and a user service."
say "It does not send a test message or start the watcher in this step."
python3 install.py --configure

stage "Verify and optionally start"
if ! python3 -m pr_review_watcher doctor; then
  warn "Setup files are installed, but verification found missing access or settings."
  note "Fix the FAIL entries and rerun ./setup.sh. The watcher was not started by this wizard."
  exit 1
fi
note "These checks do not spend review tokens, send Slack messages or prove Pi provider login."
say "New installations baseline existing PRs; only later ready transitions and author comments trigger."
say "A GREEN review sends you the PR link. Approval stays manual."
if confirm "Enable and start/restart the background service now?"; then
  python3 install.py --start
else
  say "Start later: python3 install.py --start"
fi
say "Config: ~/.config/pr-review-watcher/config.toml"
say "Logs: pr-review-watcher logs --follow"
say "Status: pr-review-watcher status"
say "Stop: systemctl --user stop pr-review-watcher.service"
finish
